CREATE FUNCTION dbt_apy.sync_dup_chk_family_members() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN IF TG_OP = 'INSERT' THEN IF NEW.application_status = 'SUBMITTED' AND NOT NEW.is_deleted THEN INSERT INTO dup_chk.family_members ( id, member_name, aadhaar_no, mobile_no, bank_account_no, epic_no, digital_ration_card_no ) VALUES ( NEW.id, NEW.member_name, NEW.aadhaar_no, NEW.mobile_no, NEW.bank_account_no, NEW.epic_no, NEW.digital_ration_card_no ) ON CONFLICT (id) DO NOTHING; END IF; ELSIF TG_OP = 'UPDATE' THEN IF OLD.aadhaar_no <> NEW.aadhaar_no AND OLD.next_level_role_id > 0 THEN UPDATE dup_chk.family_members SET aadhaar_no=NEW.aadhaar_no WHERE id=NEW.id; ELSIF NEW.next_level_role_id < 0 OR NEW.is_deleted=TRUE THEN DELETE FROM dup_chk.family_members WHERE id=NEW.id; END IF; END IF; RETURN NEW; END; $$;


ALTER FUNCTION dbt_apy.sync_dup_chk_family_members() OWNER TO postgres;

